110|export function PanelsModal({
111|  ch,
112|  chapterTitle,
113|  panels,
114|  onClose,
115|  onOpenArt,
116|}: {
117|  ch: number;
118|  chapterTitle: string;
119|  panels: ChapterPanel[];
120|  onClose: () => void;
121|  onOpenArt: (src: string, caption: string, opener: HTMLElement | null) => void;
122|}) {
123|  const chapterLabel = `Chapter ${ch}, ${chapterTitle}`;
124|  const closeRef = useRef<HTMLButtonElement | null>(null);
125|  const boxRef = useRef<HTMLDivElement | null>(null);
126|  // Session cache first, bundled art next, placeholder last.
127|  const [resolved] = useState<ResolvedPanel[]>(() =>
128|    panels.map((p) => ({ ...p, url: getCachedScenePicture(p.sceneId)?.url ?? p.art })),
129|  );
130|
131|  useEffect(() => {
132|    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
133|    closeRef.current?.focus();
134|    const onKey = (event: KeyboardEvent) => {
135|      if (event.key === "Escape") {
136|        // The shared lightbox sits above the modal and closes itself.
137|        if (document.querySelector(".lightbox")) return;
138|        event.stopPropagation();
139|        onClose();
140|        return;
141|      }
142|      if (event.key !== "Tab" || !boxRef.current) return;
143|      const items = [...boxRef.current.querySelectorAll<HTMLElement>("button, [href], [tabindex]:not([tabindex='-1'])")].filter(
144|        (el) => !el.hasAttribute("disabled"),
145|      );
146|      if (items.length === 0) return;
147|      const first = items[0] as HTMLElement;
148|      const last = items[items.length - 1] as HTMLElement;
149|      if (event.shiftKey && document.activeElement === first) {
150|        event.preventDefault();
151|        last.focus();
152|      } else if (!event.shiftKey && document.activeElement === last) {
153|        event.preventDefault();
154|        first.focus();
155|      }
156|    };
157|    document.addEventListener("keydown", onKey, true);
158|    return () => {
159|      document.removeEventListener("keydown", onKey, true);
160|      opener?.focus?.();
161|    };
162|  }, [onClose]);
163|
164|  return (
165|    <div className="panels-modal" role="dialog" aria-modal="true" aria-label={chapterLabel}>
166|      <div ref={boxRef} className="panels-box">
167|        <button ref={closeRef} type="button" className="panels-x" onClick={onClose} aria-label="Close">
168|          ×
169|        </button>
170|        <p className="panels-head">
171|          Chapter {ch} · {chapterTitle}
172|        </p>
173|        <div className={resolved.length <= 4 ? "panel-grid two" : "panel-grid"}>
174|          {resolved.map((p, i) =>
175|            p.url ? (
176|              <button
177|                key={p.sceneId}
178|                type="button"
179|                className="panel"
180|                onClick={(e) => onOpenArt(p.url as string, p.caption, e.currentTarget)}
181|                aria-label={`Panel ${i + 1}: ${p.caption}`}
182|              >
183|                <span className="panel-num" aria-hidden="true">
184|                  {i + 1}
185|                </span>
186|                <img src={p.url} alt="" />
187|                <span className="panel-cap">{p.caption}</span>
188|              </button>
189|            ) : (
190|              <div key={p.sceneId} className="panel bare" aria-label={`Panel ${i + 1}: ${p.caption}`}>
191|                <span className="panel-num" aria-hidden="true">
