1|// Chapter panels: the offer card on the cover, the spoiler gate, and
2|// the comic-page modal. Port of the .proto/v3 panels look, not its code.
3|"use client";
4|
5|import { useEffect, useRef, useState } from "react";
6|import { PANELS_NAME } from "./panels";
7|import type { ChapterPanel } from "./panels";
8|import { getCachedScenePicture } from "./use-pictures";
9|
10|export const SPOILER_LINE = "The whole chapter, told in pictures. It gives away what happens, so you may want to read first.";
11|
12|function EyeOffIcon() {
13|  return (
14|    <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true">
15|      <path d="M2.5 2.5l11 11M6.6 3.2c.5-.1 1-.2 1.4-.2 2.8 0 5.2 2.4 6 5-1 3.2-3.2 5-6 5-1 0-2-.3-2.8-.7M4 4.6C2.7 5.7 2 7 2 8c.8 2.6 3.2 5 6 5 1 0 2-.3 2.9-.8" />
16|    </svg>
17|  );
18|}
19|
20|function PencilIcon() {
21|  return (
22|    <svg width="18" height="18" viewBox="0 0 16 16" aria-hidden="true">
23|      <path d="M11.5 2.5l2 2L5 13l-2.7.7L3 11l8.5-8.5Z" />
24|    </svg>
25|  );
26|}
27|
28|// Blurred strip of the chapter's thumbs: spoiler-safe, decorative only.
29|export function BlurredThumbs({ panels, unblurredCount }: { panels: ChapterPanel[]; unblurredCount?: number }) {
30|  const show = unblurredCount === undefined ? panels : panels.slice(0, unblurredCount);
31|  return (
32|    <div className={unblurredCount === undefined ? "thumb-strip" : "thumb-strip open"} aria-hidden="true">
33|      {show.map((p) =>
34|        p.art ? (
35|          <img key={p.sceneId} src={p.art} alt="" />
36|        ) : (
37|          <span key={p.sceneId} className="thumb-empty" />
38|        ),
39|      )}
40|    </div>
41|  );
42|}
43|
44|export function PanelsOfferCard({ panels, onShowAnyway, onReadFirst }: { panels: ChapterPanel[]; onShowAnyway: () => void; onReadFirst: () => void }) {
45|  return (
46|    <section className="panels-offer" aria-label={PANELS_NAME}>
47|      <BlurredThumbs panels={panels} />
48|      <div className="panels-offer-row">
49|        <span className="panels-eye">
50|          <EyeOffIcon />
51|        </span>
52|        <div>
53|          <p className="panels-name">{PANELS_NAME}</p>
54|          <p className="panels-spoiler">{SPOILER_LINE}</p>
55|        </div>
56|      </div>
57|      <div className="panels-btns">
58|        <button type="button" className="panels-primary" onClick={onShowAnyway}>
59|          Show me anyway
60|        </button>
61|        <button type="button" className="panels-quiet" onClick={onReadFirst}>
62|          I&apos;ll read first
63|        </button>
64|      </div>
65|    </section>
66|  );
67|}
68|
69|export function PanelsQuietLink({ onOpen }: { onOpen: (opener: HTMLElement | null) => void }) {
70|  return (
71|    <button type="button" className="panels-link" onClick={(e) => onOpen(e.currentTarget)}>
72|      {PANELS_NAME}
73|    </button>
74|  );
75|}
76|
77|// Small gate in front of the panels: the spoiler line plus a choice.
78|// It never repeats the panels name.
79|export function SpoilerGateDialog({ onShow, onNotYet }: { onShow: () => void; onNotYet: () => void }) {
80|  const showRef = useRef<HTMLButtonElement | null>(null);
81|  useEffect(() => {
82|    showRef.current?.focus();
83|    const onKey = (event: KeyboardEvent) => {
84|      if (event.key === "Escape") onNotYet();
85|    };
86|    document.addEventListener("keydown", onKey);
87|    return () => document.removeEventListener("keydown", onKey);
88|  }, [onNotYet]);
89|  return (
90|    <div className="gate-wrap" role="dialog" aria-modal="true" aria-label="Before you look ahead">
91|      <div className="gate-card">
92|        <p>{SPOILER_LINE}</p>
93|        <div className="panels-btns">
94|          <button ref={showRef} type="button" className="panels-primary" onClick={onShow}>
95|            Show me anyway
96|          </button>
97|          <button type="button" className="panels-quiet" onClick={onNotYet}>
98|            Not yet
99|          </button>
100|        </div>
101|      </div>
102|    </div>
103|  );
104|}
105|
106|interface ResolvedPanel extends ChapterPanel {
107|  url: string | null;
108|}
109|
110|export function PanelsModal({
111|  ch,
112|  chapterTitle,
113|  panels,
114|  onClose,
115|  onOpenArt,
116|}: {
117|  ch: number;
118|  chapterTitle: string;
119|  panels: ChapterPanel[];
120|  onClose: () => void;
121|  onOpenArt: (src: string, caption: string, opener: HTMLElement | null) => void;
122|}) {
123|  const chapterLabel = `Chapter ${ch}, ${chapterTitle}`;
124|  const closeRef = useRef<HTMLButtonElement | null>(null);
125|  const boxRef = useRef<HTMLDivElement | null>(null);
126|  // Session cache first, bundled art next, placeholder last.
127|  const [resolved] = useState<ResolvedPanel[]>(() =>
128|    panels.map((p) => ({ ...p, url: getCachedScenePicture(p.sceneId)?.url ?? p.art })),
129|  );
130|
131|  useEffect(() => {
132|    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
133|    closeRef.current?.focus();
134|    const onKey = (event: KeyboardEvent) => {
135|      if (event.key === "Escape") {
136|        // The shared lightbox sits above the modal and closes itself.
137|        if (document.querySelector(".lightbox")) return;
138|        event.stopPropagation();
139|        onClose();
140|        return;
141|      }
142|      if (event.key !== "Tab" || !boxRef.current) return;
143|      const items = [...boxRef.current.querySelectorAll<HTMLElement>("button, [href], [tabindex]:not([tabindex='-1'])")].filter(
144|        (el) => !el.hasAttribute("disabled"),
145|      );
146|      if (items.length === 0) return;
147|      const first = items[0] as HTMLElement;
148|      const last = items[items.length - 1] as HTMLElement;
149|      if (event.shiftKey && document.activeElement === first) {
150|        event.preventDefault();
151|        last.focus();
152|      } else if (!event.shiftKey && document.activeElement === last) {
153|        event.preventDefault();
154|        first.focus();
155|      }
156|    };
157|    document.addEventListener("keydown", onKey, true);
158|    return () => {
159|      document.removeEventListener("keydown", onKey, true);
160|      opener?.focus?.();
161|    };
162|  }, [onClose]);
163|
164|  return (
165|    <div className="panels-modal" role="dialog" aria-modal="true" aria-label={chapterLabel}>
166|      <div ref={boxRef} className="panels-box">
167|        <button ref={closeRef} type="button" className="panels-x" onClick={onClose} aria-label="Close">
168|          ×
169|        </button>
170|        <p className="panels-head">
171|          Chapter {ch} · {chapterTitle}
172|        </p>
173|        <div className={resolved.length <= 4 ? "panel-grid two" : "panel-grid"}>
174|          {resolved.map((p, i) =>
175|            p.url ? (
176|              <button
177|                key={p.sceneId}
178|                type="button"
179|                className="panel"
180|                onClick={(e) => onOpenArt(p.url as string, p.caption, e.currentTarget)}
181|                aria-label={`Panel ${i + 1}: ${p.caption}`}
182|              >
183|                <span className="panel-num" aria-hidden="true">
184|                  {i + 1}
185|                </span>
186|                <img src={p.url} alt="" />
187|                <span className="panel-cap">{p.caption}</span>
188|              </button>
189|            ) : (
190|              <div key={p.sceneId} className="panel bare" aria-label={`Panel ${i + 1}: ${p.caption}`}>
191|                <span className="panel-num" aria-hidden="true">
192|                  {i + 1}
193|                </span>
194|                <span className="panel-hatch" aria-hidden="true">
195|                  <PencilIcon />
196|                </span>
197|                <span className="panel-cap">{p.caption}</span>
198|              </div>
199|            ),
200|          )}
201|        </div>
202|      </div>
203|    </div>
204|  );
