1|// Copy gates for chapter panels: the panels name lives in one const,
2|// user copy never says Generated, and Meta blue stays the only accent.
3|import { describe, expect, it } from "vitest";
4|import { readdirSync, readFileSync, statSync } from "node:fs";
5|import { dirname, join } from "node:path";
6|import { fileURLToPath } from "node:url";
7|
8|const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
9|
10|function sources(): { path: string; text: string }[] {
11|  const out: { path: string; text: string }[] = [];
12|  const walk = (dir: string) => {
13|    for (const name of readdirSync(dir)) {
14|      const path = join(dir, name);
15|      if (statSync(path).isDirectory()) {
16|        walk(path);
17|        continue;
18|      }
19|      if (!/\.(tsx?|css)$/.test(name) || /\.test\.[jt]sx?$/.test(name)) continue;
20|      out.push({ path, text: readFileSync(path, "utf8") });
21|    }
22|  };
23|  walk(join(root, "app"));
24|  walk(join(root, "core"));
25|  return out;
26|}
27|
28|const PURPLES = new Set(
29|  ["800080", "8e44ad", "9b59b6", "a855f7", "7c3aed", "6d28d9", "9333ea", "5b21b6", "4c1d95", "c084fc", "d8b4fe", "e9d5ff", "ee82ee", "9400d3", "9370db", "663399"],
30|);
31|
32|describe("chapter panels copy gates", () => {
33|  it("names the panels view exactly once across app and core sources", () => {
34|    const files = sources();
35|    const hits = files.filter((f) => f.text.includes("Chapter in panels")).map((f) => f.path);
36|    expect(hits).toEqual([join(root, "app", "folio", "panels.ts")]);
37|  });
38|
39|  it("never says Generated in user sources", () => {
40|    const hits = sources()
41|      .filter((f) => f.text.includes("Generated"))
42|      .map((f) => f.path);
43|    expect(hits).toEqual([]);
44|  });
45|
46|  it("uses no purple hex anywhere in app or core", () => {
47|    const hits: string[] = [];
48|    for (const f of sources()) {
49|      for (const m of f.text.matchAll(/#([0-9a-fA-F]{6})\b/g)) {
50|        if (PURPLES.has(m[1]?.toLowerCase() ?? "")) hits.push(`${f.path}: ${m[0]}`);
51|      }
52|    }
53|    expect(hits).toEqual([]);
54|  });
55|});

