1|// Chapter panels data: bundled art plus the per-session spoiler state.
2|// The client receives the current chapter's short captions only, never
3|// other chapters' or full summaries (see docs/contracts-chapters.md).
4|export const PANELS_NAME = "Chapter in panels";
5|
6|export const PANEL_ART: Record<string, string> = {
7|  c1s2: "/art/panels/cyclone-doorway.jpg",
8|  c1s3: "/art/panels/cyclone-house.jpg",
9|};
10|
11|export interface ChapterPanel {
12|  sceneId: string;
13|  caption: string;
14|  art: string | null;
15|}
16|
17|// Session memory: which chapters the reader has finished, opened
18|// anyway, or set aside. Plain sets, so a reload starts unspoiled.
19|const reachedEnd = new Set<number>();
20|const shownAnyway = new Set<number>();
21|const setAside = new Set<number>();
22|
23|export function chapterEndReached(ch: number): boolean {
24|  return reachedEnd.has(ch);
25|}
26|
27|export function markChapterEndReached(ch: number): void {
28|  reachedEnd.add(ch);
29|}
30|
31|export function panelsUnlocked(ch: number): boolean {
32|  return reachedEnd.has(ch) || shownAnyway.has(ch);
33|}
34|
35|export function markPanelsShownAnyway(ch: number): void {
36|  shownAnyway.add(ch);
37|}
38|
39|export function chapterSetAside(ch: number): boolean {
40|  return setAside.has(ch);
41|}
42|
43|export function markChapterSetAside(ch: number): void {
44|  setAside.add(ch);
45|}

