+
+/* Long titles step the number down so the cover fits with no scroll. */
+.cover-num[data-long="1"] {
+  font-size: 6.5rem;
+  margin-top: 8px;
+}
+
+.cover-num[data-long="2"] {
+  font-size: 5.5rem;
+  margin-top: 8px;
+}
+
+.cover-title {
+  margin-top: 6px;
+  margin-bottom: 2px;
+}
+
+.cover-title[data-long="1"] {
+  font-size: 36px;
+}
+
+.cover-title[data-long="2"] {
+  font-size: 30px;
+  line-height: 1.12;
+}
+
+.cover-rule {
+  border: 0;
+  border-top: 1px solid var(--color-border);
+  margin: 14px 0;
+  max-width: var(--measure-reading);
+}
+
+.panels-offer {
+  border: 1px solid var(--color-border);
+  border-radius: 10px;
+  background: var(--color-surface-soft);
+  padding: 18px;
+  margin: 4px 0 20px;
+  max-width: var(--measure-reading);
+}
+
+.thumb-strip {
+  display: flex;
+  gap: 6px;
+  pointer-events: none;
+}
+
+/* Each tile clips its own thumbnail, so the blur never eats the gaps. */
+.thumb-tile {
+  flex: 1;
+  min-width: 0;
+  border-radius: 4px;
+  overflow: hidden;
+  background: var(--color-paper-dim);
+}
+
+.thumb-tile img {
+  width: 100%;
+  height: 64px;
+  object-fit: cover;
+  display: block;
+  filter: blur(10px) saturate(0.7);
+}
+
+.thumb-strip.open .thumb-tile img {
+  filter: none;
+}
+
+/* A lone tile is a panel, not a bar. */
+.thumb-strip > :only-child {
+  flex: none;
+  width: min(180px, 100%);
+}
+
+.thumb-empty {
+  display: block;
+  height: 64px;
+  background: var(--color-paper-dim);
+}
+
+.panels-offer-row {
+  display: flex;
+  gap: 10px;
+  margin-top: 12px;
+}

